const configuredApiUrl = env.get('SGA_API_URL') || 'http://127.0.0.1:3001';
const apiBaseUrl = (/^https?:\/\//i.test(configuredApiUrl) ? configuredApiUrl : `http://${configuredApiUrl}`).replace(/\/$/, '');
msg.url = `${apiBaseUrl}/api/machines`;
msg.method = 'GET';
return msg;

const machines = Array.isArray(msg.payload) ? msg.payload : [];
const configuredApiUrl = env.get('SGA_API_URL') || 'http://127.0.0.1:3001';
const apiBaseUrl = (/^https?:\/\//i.test(configuredApiUrl) ? configuredApiUrl : `http://${configuredApiUrl}`).replace(/\/$/, '');
const now = new Date().toISOString();

const messages = machines.map((machine) => {
    const description = `${machine.name || ''} ${machine.type || ''}`.toLocaleLowerCase('pt-BR');
    const isErosion = description.includes('erosão') || description.includes('erosao');
    const isPress = description.includes('prensa') || description.includes('estamp');
    const isRunning = Math.random() > 0.15;
    const machineCode = machine.machine_code || String(machine.id).slice(0, 8);
    const payload = {
        machine_id: machine.id,
        status: isRunning ? (isPress ? 'Estampando' : 'Usinando') : 'Parada',
        timestamp: now,
        oee: isRunning ? Number((65 + Math.random() * 30).toFixed(1)) : 0,
        current_program: `SIM-${machineCode}`,
        part_count: (Number(machine.part_count) || 0) + (isRunning && Math.random() > 0.65 ? 1 : 0),
        spindle_speed: !isErosion && !isPress && isRunning ? Math.round(1200 + Math.random() * 6800) : 0,
        spindle_load: !isErosion && !isPress && isRunning ? Math.round(20 + Math.random() * 65) : 0,
        feed_rate: !isErosion && !isPress && isRunning ? Math.round(300 + Math.random() * 2200) : 0,
        wire_tension: isErosion && isRunning ? Number((8 + Math.random() * 5).toFixed(1)) : 0,
        tonnage: isPress && isRunning ? Math.round(40 + Math.random() * 160) : 0,
        strokes_per_min: isPress && isRunning ? Math.round(10 + Math.random() * 35) : 0,
        voltage: isErosion && isRunning ? Math.round(55 + Math.random() * 20) : 0,
        current: isErosion && isRunning ? Number((5 + Math.random() * 10).toFixed(1)) : 0,
        active_alarms: []
    };

    return {
        method: 'POST',
        url: `${apiBaseUrl}/api/telemetry`,
        headers: { 'content-type': 'application/json' },
        payload
    };
});

return [messages];
